def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    colors = {v for row in grid for v in row if v != 0}
    # Color 8 is the vertical anchor; align each color's whole pattern to its top row.
    anchor_rows = [r for r, row in enumerate(grid) if 8 in row]
    target_top = min(anchor_rows)
    for color in colors:
        cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == color]
        shift = min(r for r, c in cells) - target_top
        for r, c in cells:
            out[r-shift][c] = color
    return out

